#include "stdlib/ml/strided/dsgd_trainer.h"
#include "stdlib/ml/base/sgd/learning_rates.h"
#include "stdlib/ml/base/sgd/loss_functions.h"
#include "stdlib/ml/base/sgd/penalties.h"
#include "stdlib/ml/base/loss/float64/epsilon_insensitive_gradient.h"
#include "stdlib/ml/base/loss/float64/hinge_gradient.h"
#include "stdlib/ml/base/loss/float64/huber_gradient.h"
#include "stdlib/ml/base/loss/float64/log_gradient.h"
#include "stdlib/ml/base/loss/float64/modified_huber_gradient.h"
#include "stdlib/ml/base/loss/float64/squared_epsilon_insensitive_gradient.h"
#include "stdlib/ml/base/loss/float64/squared_error_gradient.h"
#include "stdlib/ml/base/loss/float64/squared_hinge_gradient.h"
#include "stdlib/math/base/special/max.h"
#include "stdlib/math/base/special/min.h"
#include "stdlib/math/base/special/pow.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/ddot.h"
#include "stdlib/blas/base/daxpy.h"
#include "stdlib/blas/base/dscal.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdbool.h>
#include <stdint.h>

static const double MIN_SCALE = 1.0e-9;
static const double MAX_DLOSS = 1.0e12;

/**
* Computes a learning rate according to the `basic` learning rate scheduler.
*
* @param t  current iteration
* @return   learning rate
*/
static double basic( const CBLAS_INT t ) {
	return 10.0 / ( 10.0*(double)t );
}

/**
* Computes a learning rate according to the `constant` learning rate scheduler.
*
* ## Notes
*
* -   The parameter list is `[ eta0 ]`.
*
* @param params  scheduler parameters
* @return        learning rate
*/
static double constant( const double *params ) {
	return params[ 0 ]; // eta0
}

/**
* Computes a learning rate according to the `invscaling` learning rate scheduler.
*
* ## Notes
*
* -   The parameter list is `[ eta0, powerT ]`.
*
* @param t       current iteration
* @param params  scheduler parameters
* @return        learning rate
*/
static double invscaling( const CBLAS_INT t, const double *params ) {
	return params[ 0 ] / stdlib_base_pow( (double)t, params[ 1 ] );
}

/**
* Computes a learning rate according to the `pegasos` learning rate scheduler.
*
* ## Notes
*
* -   The parameter list is `[ lambda ]`.
*
* @param t       current iteration
* @param params  scheduler parameters
* @return        learning rate
*/
static double pegasos( const CBLAS_INT t, const double *params ) {
	return 1.0 / ( params[ 0 ]*(double)t );
}

/**
* Computes the gradient of the epsilon-insensitive loss.
*
* ## Notes
*
* -   The parameter list is `[ epsilon ]`.
*
* @param y       target value
* @param p       predicted value
* @param params  loss function parameters
* @return        loss gradient
*/
static double epsilon_insensitive( const double y, const double p, const double *params ) {
	return stdlib_base_float64_epsilon_insensitive_gradient( 1.0, params[ 0 ], y, p );
}

/**
* Computes the gradient of the hinge loss.
*
* @param y  target value
* @param p  predicted value
* @return   loss gradient
*/
static double hinge( const double y, const double p ) {
	return stdlib_base_float64_hinge_gradient( 1.0, 1.0, y, p );
}

/**
* Computes the gradient of the Huber loss.
*
* ## Notes
*
* -   The parameter list is `[ threshold ]`.
*
* @param y       target value
* @param p       predicted value
* @param params  loss function parameters
* @return        loss gradient
*/
static double huber( const double y, const double p, const double *params ) {
	return stdlib_base_float64_huber_gradient( 1.0, params[ 0 ], y, p );
}

/**
* Computes the gradient of the log loss.
*
* @param y  target value
* @param p  predicted value
* @return   loss gradient
*/
static double log_loss( const double y, const double p ) {
	return stdlib_base_float64_log_gradient( 1.0, y, p );
}

/**
* Computes the gradient of the modified Huber loss.
*
* @param y  target value
* @param p  predicted value
* @return   loss gradient
*/
static double modified_huber( const double y, const double p ) {
	return stdlib_base_float64_modified_huber_gradient( 1.0, y, p );
}

/**
* Computes the gradient of the perceptron loss.
*
* ## Notes
*
* -   The perceptron loss is the hinge loss without a margin, and thus we resolve the gradient using the hinge loss gradient with a zero margin threshold.
*
* @param y  target value
* @param p  predicted value
* @return   loss gradient
*/
static double perceptron( const double y, const double p ) {
	return stdlib_base_float64_hinge_gradient( 1.0, 0.0, y, p );
}

/**
* Computes the gradient of the squared epsilon-insensitive loss.
*
* ## Notes
*
* -   The parameter list is `[ epsilon ]`.
*
* @param y       target value
* @param p       predicted value
* @param params  loss function parameters
* @return        loss gradient
*/
static double squared_epsilon_insensitive( const double y, const double p, const double *params ) {
	return stdlib_base_float64_squared_epsilon_insensitive_gradient( 1.0, params[ 0 ], y, p );
}

/**
* Computes the gradient of the squared error loss.
*
* @param y  target value
* @param p  predicted value
* @return   loss gradient
*/
static double squared_error( const double y, const double p ) {
	return stdlib_base_float64_squared_error_gradient( 1.0, y, p );
}

/**
* Computes the gradient of the squared hinge loss.
*
* @param y  target value
* @param p  predicted value
* @return   loss gradient
*/
static double squared_hinge( const double y, const double p ) {
	return stdlib_base_float64_squared_hinge_gradient( 1.0, 1.0, y, p );
}

/**
* Computes a scale factor by applying the identity decay.
*
* @param scaleFactor  current scale factor
* @return             scale factor
*/
static double identity_decay( const double scaleFactor ) {
	return scaleFactor;
}

/**
* Computes a scale factor by applying the L2 decay.
*
* ## Notes
*
* -   The parameter list is `[ lambda, l1Ratio ]`.
*
* @param scaleFactor  current scale factor
* @param eta          learning rate
* @param params       penalty parameters
* @return             scale factor
*/
static double l2_decay( const double scaleFactor, const double eta, const double *params ) {
	return scaleFactor * stdlib_base_max( 0.0, 1.0-( ( 1.0-params[ 1 ] )*eta*params[ 0 ] ) );
}

/**
* Applies the cumulative L1 penalty to a weight vector.
*
* ## Notes
*
* -   The parameter list is `[ lambda, l1Ratio ]`.
*
* @param N            number of features
* @param u            cumulative L1 penalty accumulated thus far
* @param eta          learning rate
* @param scaleFactor  current scale factor applied to the stored weights
* @param w            weight array
* @param strideW      stride length for `w`
* @param offsetW      starting index for `w`
* @param ws           workspace array tracking the total L1 shrinkage applied to each feature
* @param strideWS     stride length for `ws`
* @param offsetWS     starting index for `ws`
* @param params       penalty parameters
* @return             cumulative L1 penalty
*/
static double l1_truncation( const CBLAS_INT N, double u, const double eta, const double scaleFactor, double *w, const CBLAS_INT strideW, const CBLAS_INT offsetW, double *ws, const CBLAS_INT strideWS, const CBLAS_INT offsetWS, const double *params ) {
	CBLAS_INT wsIdx;
	CBLAS_INT idx;
	CBLAS_INT j;
	double z;

	u += ( eta*params[ 0 ]*params[ 1 ] );
	for ( j = 0; j < N; j++ ) {
		idx = offsetW + ( j*strideW );
		wsIdx = offsetWS + ( j*strideWS );
		z = w[ idx ];
		if ( scaleFactor*z > 0.0 ) {
			w[ idx ] = stdlib_base_max( 0.0, z-( ( u+ws[ wsIdx ] )/scaleFactor ) );
		} else if ( scaleFactor*z < 0.0 ) {
			w[ idx ] = stdlib_base_min( 0.0, z+( ( u-ws[ wsIdx ] )/scaleFactor ) );
		}
		ws[ wsIdx ] += scaleFactor*( w[ idx ]-z );
	}
	return u;
}

/**
* Computes a learning rate according to a specified learning rate scheduler.
*
* @param learningRate  learning rate scheduler
* @param t             current iteration
* @param params        scheduler parameters
* @return              learning rate
*/
static double stdlib_ml_sgd_learning_rate( const enum STDLIB_ML_SGD_LEARNING_RATE learningRate, const CBLAS_INT t, const double *params ) {
	switch ( learningRate ) {
	case STDLIB_ML_SGD_CONSTANT:
		return constant( params );
	case STDLIB_ML_SGD_INVSCALING:
		return invscaling( t, params );
	case STDLIB_ML_SGD_PEGASOS:
		return pegasos( t, params );
	case STDLIB_ML_SGD_BASIC:
	default:
		return basic( t );
	}
}

/**
* Computes the gradient of a specified loss function.
*
* @param lossFunction  loss function
* @param y             target value
* @param p             predicted value
* @param params        loss function parameters
* @return              loss gradient
*/
static double stdlib_ml_sgd_loss_gradient( const enum STDLIB_ML_SGD_LOSS_FUNCTION lossFunction, const double y, const double p, const double *params ) {
	switch ( lossFunction ) {
	case STDLIB_ML_SGD_EPSILON_INSENSITIVE:
		return epsilon_insensitive( y, p, params );
	case STDLIB_ML_SGD_HUBER:
		return huber( y, p, params );
	case STDLIB_ML_SGD_LOG:
		return log_loss( y, p );
	case STDLIB_ML_SGD_MODIFIED_HUBER:
		return modified_huber( y, p );
	case STDLIB_ML_SGD_PERCEPTRON:
		return perceptron( y, p );
	case STDLIB_ML_SGD_SQUARED_EPSILON_INSENSITIVE:
		return squared_epsilon_insensitive( y, p, params );
	case STDLIB_ML_SGD_SQUARED_ERROR:
		return squared_error( y, p );
	case STDLIB_ML_SGD_SQUARED_HINGE:
		return squared_hinge( y, p );
	case STDLIB_ML_SGD_HINGE:
	default:
		return hinge( y, p );
	}
}

/**
* Computes a scale factor according to the weight decay associated with a specified penalty.
*
* @param penalty      regularization function
* @param scaleFactor  current scale factor
* @param eta          learning rate
* @param params       penalty parameters
* @return             scale factor
*/
static double stdlib_ml_sgd_decay( const enum STDLIB_ML_SGD_PENALTY penalty, const double scaleFactor, const double eta, const double *params ) {
	switch ( penalty ) {
	case STDLIB_ML_SGD_ELASTICNET:
	case STDLIB_ML_SGD_L2:
		return l2_decay( scaleFactor, eta, params );
	case STDLIB_ML_SGD_L1:
	case STDLIB_ML_SGD_NONE:
	default:
		return identity_decay( scaleFactor );
	}
}

/**
* Applies the truncation associated with a specified penalty to a weight vector.
*
* @param penalty      regularization function
* @param N            number of features
* @param u            cumulative L1 penalty accumulated thus far
* @param eta          learning rate
* @param scaleFactor  current scale factor applied to the stored weights
* @param w            weight array
* @param strideW      stride length for `w`
* @param offsetW      starting index for `w`
* @param ws           workspace array tracking the total L1 shrinkage applied to each feature
* @param strideWS     stride length for `ws`
* @param offsetWS     starting index for `ws`
* @param params       penalty parameters
* @return             cumulative L1 penalty
*/
static double stdlib_ml_sgd_truncation( const enum STDLIB_ML_SGD_PENALTY penalty, const CBLAS_INT N, const double u, const double eta, const double scaleFactor, double *w, const CBLAS_INT strideW, const CBLAS_INT offsetW, double *ws, const CBLAS_INT strideWS, const CBLAS_INT offsetWS, const double *params ) {
	switch ( penalty ) {
	case STDLIB_ML_SGD_ELASTICNET:
	case STDLIB_ML_SGD_L1:
		return l1_truncation( N, u, eta, scaleFactor, w, strideW, offsetW, ws, strideWS, offsetWS, params );
	case STDLIB_ML_SGD_L2:
	case STDLIB_ML_SGD_NONE:
	default:
		return u;
	}
}

/**
* Trains a linear model via stochastic gradient descent.
*
* ## Notes
*
* -   When `params->fitIntercept` is `true`, `w` must have `N+1` indexed elements, as the fitted intercept is written to the element following the `N` feature weights.
* -   Upon return, `w` contains effective (i.e., fully rescaled) weights.
*
* @param layout    storage layout of `X`
* @param M         number of samples
* @param N         number of features
* @param X         input matrix
* @param LDX       stride of the major dimension of `X`
* @param y         target array
* @param strideY   stride length for `y`
* @param w         weight array
* @param strideW   stride length for `w`
* @param ws        workspace array
* @param strideWS  stride length for `ws`
* @param params    parameters
* @return          `w`
*/
double* API_SUFFIX(stdlib_strided_dsgd_trainer)( const CBLAS_LAYOUT layout, const CBLAS_INT M, const CBLAS_INT N, const double *X, const CBLAS_INT LDX, const double *y, const CBLAS_INT strideY, double *w, const CBLAS_INT strideW, double *ws, const CBLAS_INT strideWS, const struct stdlib_ml_sgd_float64_params *params ) {
	CBLAS_INT sx1;
	CBLAS_INT sx2;
	CBLAS_INT ows;
	CBLAS_INT oy;
	CBLAS_INT ow;

	// Check if we can early return...
	if ( M <= 0 || N <= 0 ) {
		return w;
	}
	if ( layout == CblasColMajor ) {
		sx1 = 1;
		sx2 = LDX;
	} else { // layout == CblasRowMajor
		sx1 = LDX;
		sx2 = 1;
	}
	oy = (CBLAS_INT)stdlib_strided_stride2offset( (int64_t)M, (int64_t)strideY );
	ow = (CBLAS_INT)stdlib_strided_stride2offset( (int64_t)N, (int64_t)strideW );
	ows = (CBLAS_INT)stdlib_strided_stride2offset( (int64_t)N, (int64_t)strideWS );
	return API_SUFFIX(stdlib_strided_dsgd_trainer_ndarray)( M, N, X, sx1, sx2, 0, y, strideY, oy, w, strideW, ow, ws, strideWS, ows, params );
}

/**
* Trains a linear model via stochastic gradient descent using alternative indexing semantics.
*
* ## Notes
*
* -   When `params->fitIntercept` is `true`, `w` must have `N+1` indexed elements, as the fitted intercept is written to the element following the `N` feature weights.
* -   Upon return, `w` contains effective (i.e., fully rescaled) weights.
*
* @param M          number of samples
* @param N          number of features
* @param X          input matrix
* @param strideX1   stride of the first dimension of `X`
* @param strideX2   stride of the second dimension of `X`
* @param offsetX    starting index for `X`
* @param y          target array
* @param strideY    stride length for `y`
* @param offsetY    starting index for `y`
* @param w          weight array
* @param strideW    stride length for `w`
* @param offsetW    starting index for `w`
* @param ws         workspace array
* @param strideWS   stride length for `ws`
* @param offsetWS   starting index for `ws`
* @param params     parameters
* @return           `w`
*/
double* API_SUFFIX(stdlib_strided_dsgd_trainer_ndarray)( const CBLAS_INT M, const CBLAS_INT N, const double *X, const CBLAS_INT strideX1, const CBLAS_INT strideX2, const CBLAS_INT offsetX, const double *y, const CBLAS_INT strideY, const CBLAS_INT offsetY, double *w, const CBLAS_INT strideW, const CBLAS_INT offsetW, double *ws, const CBLAS_INT strideWS, const CBLAS_INT offsetWS, const struct stdlib_ml_sgd_float64_params *params ) {
	enum STDLIB_ML_SGD_LOSS_FUNCTION lossFunction;
	enum STDLIB_ML_SGD_LEARNING_RATE learningRate;
	enum STDLIB_ML_SGD_PENALTY penalty;
	double penaltyParams[ 2 ];
	double scaleFactor;
	double intercept;
	bool fitIntercept;
	int32_t maxIter;
	int32_t epoch;
	double update;
	double dloss;
	double eta;
	double p;
	double u;
	CBLAS_INT ox;
	CBLAS_INT oy;
	CBLAS_INT i;
	CBLAS_INT t;

	// Check if we can early return...
	if ( M <= 0 || N <= 0 ) {
		return w;
	}
	penalty = (enum STDLIB_ML_SGD_PENALTY)params->penalty;
	learningRate = (enum STDLIB_ML_SGD_LEARNING_RATE)params->learningRate;
	lossFunction = (enum STDLIB_ML_SGD_LOSS_FUNCTION)params->lossFunction;
	fitIntercept = params->fitIntercept;
	intercept = params->intercept;
	maxIter = params->maxIter;

	// Resolve the effective L1 ratio, as `l1` and `l2` are the limiting cases of `elasticnet`...
	penaltyParams[ 0 ] = params->penaltyParams[ 0 ];
	if ( penalty == STDLIB_ML_SGD_L2 ) {
		penaltyParams[ 1 ] = 0.0;
	} else if ( penalty == STDLIB_ML_SGD_L1 ) {
		penaltyParams[ 1 ] = 1.0;
	} else {
		penaltyParams[ 1 ] = params->penaltyParams[ 1 ];
	}

	t = 1;
	u = 0.0;
	scaleFactor = 1.0;
	for ( epoch = 1; epoch <= maxIter; epoch++ ) {
		ox = offsetX;
		oy = offsetY;
		for ( i = 0; i < M; i++ ) {
			p = ( scaleFactor*API_SUFFIX(c_ddot_ndarray)( N, w, strideW, offsetW, X, strideX2, ox ) ) + intercept;

			eta = stdlib_ml_sgd_learning_rate( learningRate, t, params->learningRateParams );

			dloss = stdlib_ml_sgd_loss_gradient( lossFunction, y[ oy ], p, params->lossFunctionParams );
			if ( dloss < -MAX_DLOSS ) {
				dloss = -MAX_DLOSS;
			} else if ( dloss > MAX_DLOSS ) {
				dloss = MAX_DLOSS;
			}
			update = -eta * dloss;

			scaleFactor = stdlib_ml_sgd_decay( penalty, scaleFactor, eta, penaltyParams );
			if ( scaleFactor < MIN_SCALE ) {
				API_SUFFIX(c_dscal_ndarray)( N, scaleFactor, w, strideW, offsetW );
				scaleFactor = 1.0;
			}

			// Gradient step: as `w_eff = w_stored*scaleFactor`, adding `update*X` to the effective weights amounts to adding `(update/scaleFactor)*X` to the stored weights...
			API_SUFFIX(c_daxpy_ndarray)( N, update/scaleFactor, X, strideX2, ox, w, strideW, offsetW );

			if ( fitIntercept ) {
				intercept += update;
			}
			u = stdlib_ml_sgd_truncation( penalty, N, u, eta, scaleFactor, w, strideW, offsetW, ws, strideWS, offsetWS, penaltyParams );

			t += 1;
			ox += strideX1;
			oy += strideY;
		}
	}
	// Fold any residual scaling back into the weights so that `w` holds effective values...
	if ( scaleFactor != 1.0 ) {
		API_SUFFIX(c_dscal_ndarray)( N, scaleFactor, w, strideW, offsetW );
		scaleFactor = 1.0;
	}
	if ( fitIntercept ) {
		w[ offsetW+( strideW*N ) ] = intercept;
	}
	return w;
}
